const DATA=""; const RANGE=5000,R=3958.8,NEUTRAL="#cbd5e1";
const alias={"United States of America":"USA","United Kingdom":"UK","Czechia":"Czech Republic","Dem. Rep. Congo":"DRC","Bosnia and Herz.":"Bosnia Herzegovina","Timor-Leste":"East Timor","eSwatini":"Eswatini"};
let socket=io(),state=null,roomCode=null,features=[],mode="normal",myId=null;
const $=s=>document.querySelector(s); socket.on("connect",()=>{myId=socket.id});
socket.on("errorMessage",m=>{$("#joinError").textContent=m; if(state) cmd("ACTION NOT AVAILABLE",m)});
socket.on("joined",x=>{roomCode=x.code;$("#joinScreen").classList.add("hidden");$("#lobby").classList.remove("hidden")});
socket.on("state",s=>{state=s; renderState()});
$("#create").onclick=()=>socket.emit("createRoom",{name:$("#name").value});
$("#join").onclick=()=>socket.emit("joinRoom",{name:$("#name").value,code:$("#roomCode").value});
$("#start").onclick=()=>socket.emit("startGame",{code:roomCode,territories:initialTerritories()});
function canon(n){return alias[n]||n}function stat(n){return n==="China"?[110,3]:n==="Russia"?[130,3]:n==="USA"?[150,3]:[20,1]}
function initialTerritories(){let o={};features.forEach(f=>{let n=canon(f.name),[i,g]=stat(n);o[n]={name:n,infantry:i,gold:g,owner:null,defences:0,city:0}});return o}
async function load(){let b=Uint8Array.from(atob(DATA),x=>x.charCodeAt(0)),s=new DecompressionStream("gzip");features=JSON.parse(await new Response(new Blob([b]).stream().pipeThrough(s)).text());draw()}
function me(){return state?.players.find(p=>p.id===myId)}function current(){return state?.players[state.current]}
function proj(lon,lat){return[(lon+180)/360*1200,(85-lat)/143*700]}function rings(g){return g.type==="Polygon"?g.coordinates:g.coordinates.flat()}function path(g){return rings(g).map(r=>r.map((p,i)=>{let q=proj(...p);return(i?"L":"M")+q[0].toFixed(1)+" "+q[1].toFixed(1)}).join(" ")+"Z").join(" ")}
function draw(){let map=$("#map");if(!features.length)return;map.innerHTML="";for(let l=-150;l<=180;l+=30){let[x]=proj(l,0);map.innerHTML+=`<line class="grid" x1="${x}" y1="0" x2="${x}" y2="700"/>`}for(let l=-45;l<=75;l+=30){let[,y]=proj(0,l);map.innerHTML+=`<line class="grid" x1="0" y1="${y}" x2="1200" y2="${y}"/>`}map.innerHTML+='<text class="title" x="20" y="28">GLOBAL COMMAND MAP</text>';features.forEach(f=>{let n=canon(f.name),t=state?.territories?.[n],p=state?.players.find(x=>x.name===t?.owner),e=document.createElementNS("http://www.w3.org/2000/svg","path");e.setAttribute("d",path(f.geometry));e.setAttribute("fill",p?p.color:NEUTRAL);e.setAttribute("class","country"+(state?.selectedBy?.[myId]===n?" selected":""));e.onclick=()=>select(n);map.append(e)})}
function cmd(a,b){$("#command").textContent=a;$("#detail").textContent=b;$("#actionCommand").textContent=a;$("#actionDetail").textContent=b}
function renderState(){if(!state)return;if(state.phase==="lobby"){renderLobby();return}$("#lobby").classList.add("hidden");$("#app").classList.remove("hidden");let p=me(),c=current();$("#turn").textContent=`● ROUND ${state.round}\n${c?.name?.toUpperCase()||""}'S TURN`;if(p)$("#stats").innerHTML=`You: ${p.name}<hr>Capital: ${p.capital||"Not chosen"}<br>Gold: ${p.gold}<br>Reserve infantry: ${p.reserve}<br>Ships: ${p.small} small, ${p.large} large<br>Attack used: ${p.attacked?"Yes":"No"}`;$("#log").textContent=state.log.join("\n\n");let selected=state.selectedBy?.[myId];if(state.phase==="capital"){let chooser=state.players[state.capitalIndex];cmd(chooser?.id===myId?"CHOOSE YOUR CAPITAL":"WAIT FOR CAPITAL SELECTION",chooser?.id===myId?"Click a neutral country. USA, Russia and China are unavailable.":`${chooser?.name} is choosing a capital.`)}else if(c?.id===myId){if(selected){let t=state.territories[selected];cmd(`YOUR TURN — ${selected} SELECTED`,t.owner===p.name?"Choose a build command, another country, or end your turn.":"Choose Attack, or select another country.")}else cmd("YOUR TURN — CHOOSE AN ACTION","Click a country or use the Command Centre.")}else cmd(`WAIT — ${c?.name}'S TURN`,"You can watch the map, but only the active player can make moves.");draw()}
function renderLobby(){$("#roomTitle").textContent=`ROOM ${state.code}`;$("#roomText").textContent=`Share this room code with friends. ${state.players.length}/8 players joined.`;$("#playerList").innerHTML=state.players.map((p,i)=>`<div class="card">${i+1}. ${p.name}${p.id===state.hostId?" — HOST":""}</div>`).join("");$("#start").style.display=state.hostId===myId?"block":"none";$("#start").disabled=state.players.length<2}
function select(country){if(!state)return;if(state.phase==="capital")socket.emit("chooseCapital",{code:roomCode,country});else socket.emit("selectCountry",{code:roomCode,country})}
function buy(type){socket.emit("buy",{code:roomCode,type})}function modeSet(m){mode=m;cmd(`BUILD ${m==="defence"?"DEFENCE":m==="city1"?"SMALL CITY":"LARGE CITY"}`,"Click one of your own countries.");}
function attack(){let target=state.selectedBy?.[myId];if(!target)return cmd("ATTACK — SELECT A COUNTRY","Click a target country first.");let access=attackAccess(target);if(!access.ok)return cmd("TARGET OUT OF RANGE",access.text);socket.emit("attack",{code:roomCode,target,access:{kind:access.kind,distance:access.distance||0}})}
function endTurn(){socket.emit("endTurn",{code:roomCode})}
function points(n){return rings(features.find(f=>canon(f.name)===n).geometry).flat()}function centroid(n){let p=points(n);return[p.reduce((s,x)=>s+x[0],0)/p.length,p.reduce((s,x)=>s+x[1],0)/p.length]}
function dist(a,b){let[x1,y1]=centroid(a),[x2,y2]=centroid(b),p1=y1*Math.PI/180,p2=y2*Math.PI/180,dp=(y2-y1)*Math.PI/180,dl=(x2-x1)*Math.PI/180,q=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(q)))}
function bbox(n){let p=points(n),xs=p.map(x=>x[0]),ys=p.map(x=>x[1]);return{minx:Math.min(...xs),maxx:Math.max(...xs),miny:Math.min(...ys),maxy:Math.max(...ys)}}
function bordering(a,b){let A=bbox(a),B=bbox(b);return !(A.maxx+.35<B.minx||B.maxx+.35<A.minx||A.maxy+.35<B.miny||B.maxy+.35<A.miny)}
function attackAccess(target){let p=me(),owned=Object.values(state.territories).filter(t=>t.owner===p.name);for(let t of owned)if(bordering(t.name,target))return{ok:true,kind:"border",text:`Bordering ${t.name}`};if(p.small+p.large<1)return{ok:false,text:"No bordering territory and no ships available."};let best=Infinity;for(let t of owned)best=Math.min(best,dist(t.name,target));return best<=RANGE?{ok:true,kind:"ship",distance:best,text:`Ship route: ${Math.round(best)} miles`}:{ok:false,text:`Closest route is ${Math.round(best)} miles. Ships can travel only 5,000 miles.`}}
$("#map").addEventListener("click",()=>{if(["defence","city1","city2"].includes(mode)){let c=state.selectedBy?.[myId];if(c){socket.emit("build",{code:roomCode,type:mode,country:c});mode="normal"}}});
load();
